#include "ec.hpp"
int main(int argc,char**argv){try{need(argc==2,"ROOT");std::string root=argv[1];auto family=load(root+"/data/family.json"),bases=load(root+"/data/ic_factorbases.json");json out=json::array();for(int cid=0;cid<46;cid++){EC ec{val(family["nodes"][cid]["a"]),val(family["nodes"][cid]["b"])};for(int g=0;g<10;g++){std::vector<Point>b;for(auto&p:bases[std::to_string(cid)][g])b.push_back(point(p));std::set<std::tuple<bool,U,U>>support;for(Point P:b)for(Point Q:b)for(int s:{1,-1})for(int t:{1,-1}){Point R=ec.op(s==1?P:ec.neg(P),t==1?Q:ec.neg(Q));support.emplace(R.infinity,R.x,R.y);}bool identity=support.count({true,0,0})==1;U nonzero=support.size()-(identity?1:0);out.push_back({{"curve",cid},{"generator",g},{"factorbase_sign_orbits",12},{"strict_two_sum_support_including_identity",support.size()},{"identity_present",identity},{"nonidentity_support",nonzero},{"uniform_nonidentity_query_probability_exact",{{"numerator",std::to_string(nonzero)},{"denominator",std::to_string(ORDER-1)}}},{"uniform_nonidentity_query_probability",double(nonzero)/double(ORDER-1)},{"single_factorbase_shortcuts_included",false}});}}save(root+"/data/ic_support_audit.json",{{"passed",true},{"bases_checked",out.size()},{"rows",out},{"definition","Strict signed two-sum support; single-factorbase hits are not a shortcut in this candidate"}});return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
